rules.css:
.hero { position: relative; padding: 115px 0px 0px; overflow: hidden; background: linear-gradient(
    125deg,
    #216772 0%,
    #2f747d 38%,
    var(--teal) 67%,
    #49949c 100%
  ); isolation: isolate; }

@keyframes talassa-button-sheen { 
  0% { transform: translateX(-180%) skewX(-20deg); opacity: 0; }
  20% { opacity: 1; }
  80% { opacity: 1; }
  100% { transform: translateX(430%) skewX(-20deg); opacity: 0; }
}

@keyframes talassa-button-sheen-auto { 
  0%, 74% { transform: translateX(-180%) skewX(-20deg); opacity: 0; }
  77% { opacity: 1; }
  86% { opacity: 1; }
  90%, 100% { transform: translateX(430%) skewX(-20deg); opacity: 0; }
}

